def path_url(self) -> str:
    """Build the path URL to use."""

    url: list[str] = []

    p = urlsplit(cast(str, self.url))

    path = p.path
    if not path:
        path = "/"

    url.append(path)

    query = p.query
    if query:
        url.append("?")
        url.append(query)

    return "".join(url)

